              {/* Availability dot */}
              <span
                className="absolute bottom-3 right-3 h-4 w-4 rounded-full border-2 border-background bg-green-400 shadow-[0_0_8px_2px_rgba(74,222,128,0.55)]"
                aria-label="Currently available"
